require_once __DIR__.'/../includes/auth.php';require_role(['super_admin','manager','receptionist','trainer']);$bid=current_branch_id();$myTrainerId=user()['role']==='trainer'?(int)(query_value('SELECT id FROM trainers WHERE user_id=?',[user()['id']])?:0):0;
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$action=$_POST['action']??'checkin';if($action==='checkin'){$code=trim(str_replace('FITCORE:','',$_POST['member_code']??''));$m=query_one('SELECT * FROM members WHERE member_code=? AND branch_id=?',[$code,$bid]);if($m&&user()['role']==='trainer'&&(int)$m['trainer_id']!==$myTrainerId){$m=false;}if(!$m){flash('danger','Member ID not found in this branch.');}elseif($m['status']!=='active'||strtotime($m['membership_end'])<strtotime(date('Y-m-d'))){flash('danger','Check-in blocked: membership is not active.');}elseif(query_value('SELECT COUNT(*) FROM attendance WHERE member_id=? AND DATE(check_in)=CURDATE()',[$m['id']])){flash('warning',$m['first_name'].' has already checked in today.');}else{db()->prepare("INSERT INTO attendance(branch_id,member_id,check_in,method) VALUES(?,?,NOW(),?)")->execute([$bid,$m['id'],$_POST['method']??'QR']);$aid=(int)db()->lastInsertId();audit_log('attendance.checkin','attendance',$aid,$m['member_code'].' checked in');flash('success',$m['first_name'].' '.$m['last_name'].' checked in successfully.');}redirect('app/attendance.php');}if($action==='checkout'){$id=(int)$_POST['id'];db()->prepare('UPDATE attendance SET check_out=NOW() WHERE id=? AND branch_id=? AND check_out IS NULL')->execute([$id,$bid]);audit_log('attendance.checkout','attendance',$id,'Member checked out');flash('success','Member checked out.');redirect('app/attendance.php');}}
if(user()['role']==='trainer'){$rows=query_all("SELECT a.*,m.member_code,CONCAT(m.first_name,' ',m.last_name) member_name,p.name plan_name FROM attendance a JOIN members m ON m.id=a.member_id LEFT JOIN membership_plans p ON p.id=m.membership_plan_id WHERE a.branch_id=? AND m.trainer_id=? AND a.check_in>=DATE_SUB(NOW(),INTERVAL 7 DAY) ORDER BY a.check_in DESC LIMIT 100",[$bid,$myTrainerId]);$today=(int)query_value('SELECT COUNT(*) FROM attendance a JOIN members m ON m.id=a.member_id WHERE a.branch_id=? AND m.trainer_id=? AND DATE(a.check_in)=CURDATE()',[$bid,$myTrainerId]);$inside=(int)query_value('SELECT COUNT(*) FROM attendance a JOIN members m ON m.id=a.member_id WHERE a.branch_id=? AND m.trainer_id=? AND DATE(a.check_in)=CURDATE() AND a.check_out IS NULL',[$bid,$myTrainerId]);$peak=query_one("SELECT HOUR(a.check_in) h,COUNT(*) c FROM attendance a JOIN members m ON m.id=a.member_id WHERE a.branch_id=? AND m.trainer_id=? AND a.check_in>=DATE_SUB(NOW(),INTERVAL 30 DAY) GROUP BY HOUR(a.check_in) ORDER BY c DESC LIMIT 1",[$bid,$myTrainerId]);}else{$rows=query_all("SELECT a.*,m.member_code,CONCAT(m.first_name,' ',m.last_name) member_name,p.name plan_name FROM attendance a JOIN members m ON m.id=a.member_id LEFT JOIN membership_plans p ON p.id=m.membership_plan_id WHERE a.branch_id=? AND a.check_in>=DATE_SUB(NOW(),INTERVAL 7 DAY) ORDER BY a.check_in DESC LIMIT 100",[$bid]);$today=(int)query_value('SELECT COUNT(*) FROM attendance WHERE branch_id=? AND DATE(check_in)=CURDATE()',[$bid]);$inside=(int)query_value('SELECT COUNT(*) FROM attendance WHERE branch_id=? AND DATE(check_in)=CURDATE() AND check_out IS NULL',[$bid]);$peak=query_one("SELECT HOUR(check_in) h,COUNT(*) c FROM attendance WHERE branch_id=? AND check_in>=DATE_SUB(NOW(),INTERVAL 30 DAY) GROUP BY HOUR(check_in) ORDER BY c DESC LIMIT 1",[$bid]);}
$pageTitle='QR Attendance';include __DIR__.'/../includes/header.php'; ?>
<div class="hero-card" style="min-height:210px"><div class="hero-copy"><span class="hero-kicker"><i class="fa-solid fa-qrcode"></i> Smart access control</span><h2>Fast, validated member check-in.</h2><p>Scan a digital member card or enter the member ID. Expired memberships are blocked automatically.</p><div class="d-flex gap-2 mt-3"><button class="btn btn-primary" data-bs-toggle="modal" data-bs-target="#scanModal"><i class="fa-solid fa-camera me-2"></i>Open QR scanner</button></div></div></div>
<div class="metric-strip mt-3"><div class="metric-box"><small>Today's check-ins</small><strong><?= $today ?></strong></div><div class="metric-box"><small>Currently inside</small><strong><?= $inside ?></strong></div><div class="metric-box"><small>30-day peak hour</small><strong><?= $peak?date('g A',strtotime(($peak['h']).':00')):'—' ?></strong></div><div class="metric-box"><small>Access mode</small><strong style="font-size:1rem">QR + Manual</strong></div></div>
<div class="grid-2"><div class="panel"><div class="panel-head"><div><h3>Manual / scanner result</h3><p>Member code from card or QR</p></div></div><form method="post" class="row g-3"><input type="hidden" name="csrf" value="<?= csrf_token() ?>"><input type="hidden" name="action" value="checkin"><div class="col-md-7"><label class="form-label">Member ID</label><input id="memberCode" name="member_code" class="form-control" placeholder="FC-1001" required autofocus></div><div class="col-md-5"><label class="form-label">Method</label><select name="method" class="form-select"><option>QR</option><option>Manual</option><option>Card</option></select></div><div class="col-12"><button class="btn btn-primary"><i class="fa-solid fa-right-to-bracket me-2"></i>Validate & check in</button></div></form></div><div class="panel"><div class="panel-head"><div><h3>Access rules</h3><p>Automatic front-desk protection</p></div></div><div class="mini-list"><div class="mini-row"><div class="mini-avatar"><i class="fa-solid fa-shield-check"></i></div><div class="grow"><strong>Membership validation</strong><small>Only active, unexpired members can enter.</small></div></div><div class="mini-row"><div class="mini-avatar"><i class="fa-solid fa-ban"></i></div><div class="grow"><strong>Duplicate prevention</strong><small>One active daily entry prevents accidental double scans.</small></div></div><div class="mini-row"><div class="mini-avatar"><i class="fa-solid fa-chart-simple"></i></div><div class="grow"><strong>Traffic analytics</strong><small>Check-ins automatically feed peak-hour reporting.</small></div></div></div></div></div>
<div class="table-card mt-3"><div class="table-toolbar"><div><strong>Recent attendance</strong><div class="text-muted" style="font-size:.68rem">Last seven days</div></div></div><div class="table-responsive"><table class="table"><thead><tr><th>Member</th><th>Date</th><th>Check in</th><th>Check out</th><th>Method</th><th class="text-end">Action</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><div class="member-cell"><div class="avatar"><?= e(initials($r['member_name'])) ?></div><div><strong><?= e($r['member_name']) ?></strong><small><?= e($r['member_code']) ?> · <?= e($r['plan_name']) ?></small></div></div></td><td><?= format_date($r['check_in']) ?></td><td><?= date('h:i A',strtotime($r['check_in'])) ?></td><td><?= $r['check_out']?date('h:i A',strtotime($r['check_out'])):'<span class="badge-soft badge-success">Inside</span>' ?></td><td><?= e($r['method']) ?></td><td class="text-end"><?php if(!$r['check_out']&&date('Y-m-d',strtotime($r['check_in']))===date('Y-m-d')): ?><form method="post" class="d-inline"><input type="hidden" name="csrf" value="<?= csrf_token() ?>"><input type="hidden" name="action" value="checkout"><input type="hidden" name="id" value="<?= $r['id'] ?>"><button class="btn btn-dark btn-sm">Check out</button></form><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div></div>
<div class="modal fade" id="scanModal"><div class="modal-dialog modal-dialog-centered"><div class="modal-content"><div class="modal-header"><div><h5>Scan member QR</h5><small class="text-muted">Allow camera permission when asked</small></div><button class="btn-close" data-bs-dismiss="modal"></button></div><div class="modal-body"><div id="reader" style="overflow:hidden;border-radius:16px"></div><p class="text-muted small mt-3 mb-0">If camera access is unavailable, close this window and enter the member ID manually.</p></div></div></div></div>
<?php $pageScript='<script src="https://unpkg.com/html5-qrcode@2.3.8/html5-qrcode.min.js"></script><script>let scanner;const modal=document.getElementById("scanModal");modal.addEventListener("shown.bs.modal",()=>{scanner=new Html5Qrcode("reader");scanner.start({facingMode:"environment"},{fps:10,qrbox:{width:240,height:240}},text=>{document.getElementById("memberCode").value=text.replace("FITCORE:","");scanner.stop();bootstrap.Modal.getInstance(modal).hide();}).catch(()=>{});});modal.addEventListener("hidden.bs.modal",()=>{if(scanner)scanner.stop().catch(()=>{});});</script>';include __DIR__.'/../includes/footer.php'; ?>